"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[831],{48521:e=>{e.exports=JSON.parse('{"functions":[{"name":"clone","desc":"Advances the clone queue. Runs in `Phases.Update`, alongside `build` and\\n`show`.\\n\\nRuns unconditionally: a clone backlog has to keep draining whether or not\\nanyone is moving or any build job still exists.","params":[{"name":"_world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function; drops the queue.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":36,"path":"src/main/server/systems/maze/clone.luau"}}],"properties":[],"types":[],"name":"clone","desc":"Copies queued prefab hierarchies node by node, using whatever the frame has\\nleft.\\n\\nThis is a stage of its own rather than a tail call inside `builder.step`,\\nbecause the queue outlives the jobs that fill it: a placement enqueued on the\\nlast frame of a build job still needs copying after that job is gone. Draining\\nfrom inside the builder meant the builder\'s own \\"no jobs left, return early\\"\\npath stranded everything still queued.","tags":["server-system"],"realm":["Server"],"source":{"line":15,"path":"src/main/server/systems/maze/clone.luau"}}')}}]);